-- Per-user portfolio notifications (in-app bell). Rows are generated by
-- scripts/generate_notifications.py after the data jobs; the dedupe key
-- makes re-runs idempotent (ON CONFLICT DO NOTHING).
CREATE TABLE user_notifications (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id     bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    kind        text   NOT NULL,  -- rating | pay_upcoming | pay_today
                                  -- | pay_confirmed | pay_overdue
                                  -- | default | anomaly
    severity    text   NOT NULL DEFAULT 'info'
                       CHECK (severity IN ('info', 'warn', 'critical')),
    isin        char(12) NOT NULL,
    title       text   NOT NULL,
    body        text   NOT NULL DEFAULT '',
    dedupe_key  text   NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    read_at     timestamptz,
    UNIQUE (user_id, dedupe_key)
);

CREATE INDEX user_notifications_feed
    ON user_notifications (user_id, created_at DESC);
